-- 26-10-2026 (op verzoek HFC): regeling verplaatst van 'Stichting gezondheidszorg Spaarneland' naar 'Fonds SGS', hernoemd en classificatie aangepast.
update public.subsidieregelingen set funder_id='8b480bc5-7fa8-4607-a96e-1841a0b020fd', naam='Projectfinanciering zorg en welzijn', updated_at=now() where id='9122f8fc-e795-4bc6-a7bf-4584f0ca383f';
insert into public.subsidieregeling_themas (subsidieregeling_id, thema_id) select '9122f8fc-e795-4bc6-a7bf-4584f0ca383f', id from public.themas where naam in ('Gezondheid','Zorg','Welzijn','Innovatie in gezondheidszorg') on conflict do nothing;
delete from public.subsidieregeling_themas where subsidieregeling_id='9122f8fc-e795-4bc6-a7bf-4584f0ca383f' and thema_id in (select id from public.themas where naam='Kwetsbare doelgroep');
insert into public.subsidieregeling_doelgroepen (subsidieregeling_id, doelgroep_id) select '9122f8fc-e795-4bc6-a7bf-4584f0ca383f', id from public.doelgroepen where naam in ('Patiënten','Chronisch zieken','Mensen met een chronische aandoening','Mensen met een beperking','Mensen met een langdurige zorgvraag') on conflict do nothing;
delete from public.subsidieregeling_doelgroepen where subsidieregeling_id='9122f8fc-e795-4bc6-a7bf-4584f0ca383f' and doelgroep_id in (select id from public.doelgroepen where naam='Mensen in een kwetsbare positie');
insert into public.funder_doelgroepen (funder_id, doelgroep_id) select '8b480bc5-7fa8-4607-a96e-1841a0b020fd', id from public.doelgroepen where naam in ('Patiënten','Chronisch zieken','Mensen met een chronische aandoening','Mensen met een beperking','Mensen met een langdurige zorgvraag') on conflict do nothing;
delete from public.funder_doelgroepen where funder_id='8b480bc5-7fa8-4607-a96e-1841a0b020fd' and doelgroep_id in (select id from public.doelgroepen where naam='Mensen in een kwetsbare positie');
